#include "test.hpp"
#include "mspa/mspa.hpp"
using namespace mspa;
int main(){RegistryBuilder b;PredicateSchema p1{};p1.id=PredicateId(1);p1.name_space=NamespaceId(10);p1.required_roles={"actor"};p1.default_relevance=0.7f;require(b.add_predicate(p1),"add predicate 1");PredicateSchema p2{};p2.id=PredicateId(2);p2.name_space=NamespaceId(10);require(b.add_predicate(p2),"add predicate 2");PredicateSchema p3{};p3.id=PredicateId(3);p3.name_space=NamespaceId(10);require(b.add_predicate(p3),"add predicate 3");InferenceRuleData r1{};r1.id=1;r1.premises={{PredicateId(1),true}};r1.conclusion=PredicateId(2);r1.conclusion_namespace=NamespaceId(10);r1.base_certainty=0.9f;require(b.add_inference_rule(r1),"add inference 1");InferenceRuleData r2{};r2.id=2;r2.premises={{PredicateId(2),true}};r2.conclusion=PredicateId(3);r2.conclusion_namespace=NamespaceId(10);r2.base_certainty=0.8f;require(b.add_inference_rule(r2),"add inference 2");ConsiderationSchema cs{};cs.id="danger";cs.weight=-2.0f;cs.curve={{0,0},{1,1}};require(b.add_consideration(cs),"consideration");ActionSchema as{};as.id=ActionTypeId(9);as.name_space=NamespaceId(10);as.considerations={"danger"};require(b.add_action_schema(as),"action schema");auto reg=b.publish();Proposition invalid{};invalid.predicate=PredicateId(1);invalid.name_space=NamespaceId(10);require(!validate_proposition(invalid,reg),"required role enforced");Proposition fact=invalid;fact.arguments.push_back({"actor","x"});require(validate_proposition(fact,reg),"valid proposition");auto h=InferenceEngine::infer_registry_rules({fact},reg,{16,16,4});require(h&&h.value_if()->size()==2,"multi-step inference");require(h.value_if()->back().proposition.predicate==PredicateId(3),"second inference depth");DomainPack pack{};pack.metadata.id=PackId(1);pack.metadata.name_space=NamespaceId(20);pack.metadata.name="pack";PredicateSchema pp{};pp.id=PredicateId(20);pp.name_space=NamespaceId(20);pack.predicates.push_back(pp);require(validate_domain_pack(pack),"domain pack valid");RegistryBuilder bb(reg);require(apply_domain_pack(bb,pack),"domain pack apply");require(bb.publish().find(PredicateId(20))!=nullptr,"pack published");std::cout<<"semantics ok\n";}
